import json
import math
from pathlib import Path

DEFAULTS = Path(__file__).resolve().parents[1] / 'config' / 'shared.json'

def billable(weight, rounding=None):
    if rounding is None:
        rounding = json.loads(DEFAULTS.read_text(encoding='utf-8'))['rounding']
    return math.ceil(weight) if rounding == 'up' else round(weight)
